#include <iostream>
#include <string>
#include <algorithm>
#include <cctype>

int main() {
    int totalChars;
    std::cin >> totalChars;
    std::cin.ignore(); // To consume the newline after the integer input
    std::string inputLine;
    std::getline(std::cin, inputLine);

    int totalWordsInBraces = 0;
    int maxWordLength = 0;
    bool inBraces = false;
    std::string currentWord;

    auto processWord = [&](const std::string& word, bool inBracesFlag) {
        int length = static_cast<int>(word.length());
        if (length > 0) {
            if (inBracesFlag) {
                totalWordsInBraces++;
            } else {
                maxWordLength = std::max(maxWordLength, length);
            }
        }
    };

    for (int index = 0; index < totalChars; ++index) {
        char currentChar = inputLine[index];

        if (currentChar == '_') {
            processWord(currentWord, inBraces);
            currentWord.clear();
        } else if (currentChar == '(') {
            processWord(currentWord, inBraces);
            currentWord.clear();
            inBraces = true;
        } else if (currentChar == ')') {
            processWord(currentWord, inBraces);
            currentWord.clear();
            inBraces = false;
        } else if (std::isalpha(static_cast<unsigned char>(currentChar))) {
            currentWord += currentChar;
        }
    }

    // Process the last word if any
    processWord(currentWord, inBraces);

    std::cout << maxWordLength << " " << totalWordsInBraces << std::endl;

    return 0;
}
